// === Tab: mySketch ===
let simplex;
let dust = [];
let gravity;
let font;
let smileyPos, smileyRadius;
let repulsionForce = 0.6;
let repulsionRadius = 80;

function preload() {
  font = loadFont('https://openprocessing.org/sketch/2548626/files/FamiljenGrotesk-VariableFont_wght.ttf');
}

function setup() {
  createCanvas(400, 400);
  gravity = createVector(0, 0.01);
  simplex = new openSimplexNoise(Date.now());

  smileyPos = createVector(200, 200);
  smileyRadius = 75;

  background('#f4f1de');
}

function draw() {
  background('#f4f1de');

  drawSmiley();
  drawText(); // Ajout du texte

  for (let i = 0; i < 6; i++) {
    dust.push(new Particle());
  }

  for (let i = dust.length - 1; i >= 0; i--) {
    dust[i].move();
    dust[i].checkCollision();
    dust[i].applyRepulsion();
    dust[i].show();
    if (dust[i].off()) {
      dust.splice(i, 1);
    }
  }

  fill('#f4f1de');
  noStroke();
  rect(0, 0, width, 60);
  rect(0, 0, 60, height);
  rect(340, 0, 60, height);
  rect(0, 340, width, 60);
}

class Particle {
  constructor() {
    let side = floor(random(4));
    if (side === 0) {
      this.pos = createVector(random(width), -10);
      this.vel = createVector(random(-0.5, 0.5), random(0.5, 1));
    } else if (side === 1) {
      this.pos = createVector(random(width), height + 10);
      this.vel = createVector(random(-0.5, 0.5), random(-1, -0.5));
    } else if (side === 2) {
      this.pos = createVector(-10, random(height));
      this.vel = createVector(random(0.5, 1), random(-0.5, 0.5));
    } else {
      this.pos = createVector(width + 10, random(height));
      this.vel = createVector(random(-1, -0.5), random(-0.5, 0.5));
    }
  }

  move() {
    let windA = map(simplex.noise3D(this.pos.x / 70, this.pos.y / 100, frameCount / 200), -1, 1, -HALF_PI, HALF_PI);
    let windMag = map(simplex.noise3D(this.pos.x / 70, this.pos.y / 100, frameCount / 150), -1, 1, 0, 0.04);
    let wind = p5.Vector.fromAngle(windA);
    wind.setMag(windMag);
    this.vel.add(wind);
    this.vel.add(gravity);
    this.vel.limit(2);
    this.pos.add(this.vel);
  }

  checkCollision() {
    let d = dist(this.pos.x, this.pos.y, smileyPos.x, smileyPos.y);
    if (d < smileyRadius) {
      let normal = p5.Vector.sub(this.pos, smileyPos).normalize();
      this.vel.reflect(normal);
      this.vel.mult(1.2);
    }
  }

  applyRepulsion() {
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) || touches.length > 0) {
      let repeller;
      if (touches.length > 0) {
        repeller = createVector(touches[0].x, touches[0].y);
      } else {
        repeller = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      }

      var d = dist(this.pos.x, this.pos.y, repeller.x, repeller.y);
      if (d < repulsionRadius) {
        let force = p5.Vector.sub(this.pos, repeller);
        force.setMag(repulsionForce);
        this.vel.add(force);
        this.vel.limit(3);
      }
    }
  }

  show() {
    blendMode(MULTIPLY);
    fill('#ff5733');
    noStroke();
    ellipse(this.pos.x, this.pos.y, 16, 16);
    blendMode(BLEND);
  }

  off() {
    return this.pos.x < -20 || this.pos.x > width + 20 || this.pos.y < -20 || this.pos.y > height + 20;
  }
}

function drawSmiley() {
  push();
  translate(smileyPos.x, smileyPos.y);
  fill('#ffd700');
  stroke('#ff5733');
  strokeWeight(2);
  ellipse(0, 0, smileyRadius * 2, smileyRadius * 2);

  fill(0);
  noStroke();
  ellipse(-30, -20, 20, 20);
  ellipse(30, -20, 20, 20);

  noFill();
  stroke(0);
  strokeWeight(3);
  arc(0, 20, 80, 40, 0, PI);
  pop();
}

function drawText() {
  fill('#ff5733');
  textFont(font);
  textSize(40);
  textAlign(CENTER, CENTER);
  text('PROTÉGEZ', width / 2, smileyPos.y - smileyRadius - 20);

}

